CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(120) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL);
CREATE TABLE properties (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(150) NOT NULL,address VARCHAR(255) NOT NULL,description VARCHAR(500),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL);
CREATE TABLE rooms (id BIGINT PRIMARY KEY AUTO_INCREMENT,property_id BIGINT NOT NULL,code VARCHAR(30) NOT NULL,monthly_rent DECIMAL(12,2) NOT NULL,capacity INT NOT NULL,status VARCHAR(20) NOT NULL,description VARCHAR(500),created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,CONSTRAINT fk_room_property FOREIGN KEY(property_id) REFERENCES properties(id),CONSTRAINT uk_room_property_code UNIQUE(property_id,code));
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT,actor VARCHAR(160) NOT NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id VARCHAR(80),detail VARCHAR(1000),occurred_at TIMESTAMP NOT NULL);
